'use strict';
// Local-only GLSL raymarched scenes, tunable themes and motion. No network shaders.
window.Spider3DShaders=Object.freeze({vertex:"attribute vec2 a_position;\nvarying vec2 v_uv;\nvoid main(){ v_uv=a_position;gl_Position=vec4(a_position,0.0,1.0); }",fragment:"#ifdef GL_FRAGMENT_PRECISION_HIGH\nprecision highp float;\n#else\nprecision mediump float;\n#endif\nvarying vec2 v_uv;\nuniform vec2 u_resolution;\nuniform float u_time,u_bass,u_mid,u_high,u_mode,u_playing;\nuniform vec3 u_theme;\nuniform sampler2D u_spectrum;\nfloat fft(float p){return texture2D(u_spectrum,vec2(clamp(p,0.005,0.995),0.5)).r;}\nmat2 rot(float a){return mat2(cos(a),-sin(a),sin(a),cos(a));}\nfloat box3(vec3 p,vec3 b){vec3 q=abs(p)-b;return length(max(q,0.0))+min(max(q.x,max(q.y,q.z)),0.0);}\nfloat hash2(vec2 p){return fract(sin(dot(p,vec2(127.1,311.7)))*43758.5453);}\nfloat scene(vec3 p){\n if(u_mode<0.5){\n   p.xy=rot(p.z*0.12+u_time*0.22)*p.xy;\n   float angle=atan(p.y,p.x);\n   float radius=1.7+0.35*u_bass+0.3*fft(fract((angle+3.14159)/6.28318));\n   float wall=abs(length(p.xy)-radius)-0.055;\n   float ring=abs(sin(p.z*2.8-u_time*1.3))-0.23;\n   return max(wall,ring*0.09);\n }\n if(u_mode<1.5){\n   vec2 cell=floor(p.xz/0.72+0.5);\n   vec2 local=fract(p.xz/0.72+0.5)-0.5;\n   float energy=fft(fract((cell.x+9.0)/18.0));\n   float h=0.10+energy*3.8+(0.08+u_bass*0.2)*abs(sin(cell.y*0.3+u_time));\n   float block=box3(vec3(local.x*0.72,p.y-h*0.5,local.y*0.72),vec3(0.24,h*0.5,0.24));\n   return min(block,p.y+0.04);\n }\n if(u_mode<2.5){\n   vec3 q=p;q.xz=rot(u_time*0.18)*q.xz;\n   float torus=length(vec2(length(q.xz)-2.0,q.y))-0.09-0.1*u_bass;\n   for(int i=0;i<7;i++){\n     float a=float(i)*0.8976+u_time*(0.15+float(i)*0.025);\n     vec3 orb=vec3(sin(a)*(1.6+u_mid),cos(a*1.5)*1.25,cos(a)*(1.6+u_mid));\n     torus=min(torus,length(q-orb)-(0.16+fft(float(i)/7.0)*0.30));\n   }\n   return torus;\n }\n vec2 cell=floor(p.xz/1.12+0.5);\n vec2 local=(fract(p.xz/1.12+0.5)-0.5)*1.12;\n float shape=hash2(cell),energy=fft(fract((cell.x+11.0)/22.0));\n float h=0.45+shape*3.8+energy*3.0;\n float building=box3(vec3(local.x,p.y-h*0.5,local.y),vec3(0.36,h*0.5,0.39));\n return min(building,p.y+0.05);\n}\nvec3 normalAt(vec3 p){\n vec2 e=vec2(0.015,0.0);\n return normalize(vec3(scene(p+e.xyy)-scene(p-e.xyy),scene(p+e.yxy)-scene(p-e.yxy),scene(p+e.yyx)-scene(p-e.yyx)));\n}\nvec3 background(vec3 rd,vec2 uv){\n float halo=pow(max(0.0,1.0-length(uv)*0.7),3.0);\n vec3 base=mix(vec3(0.009,0.006,0.020),vec3(0.10,0.024,0.20),halo);\n if(u_mode>2.5)base=mix(base,vec3(0.18,0.016,0.07),halo*0.5);\n return base+0.014*sin(rd*11.0+u_time*0.2);\n}\nvoid main(){\n vec2 uv=(gl_FragCoord.xy-0.5*u_resolution)/max(1.0,u_resolution.y);\n vec3 ro,target;\n if(u_mode<0.5){ro=vec3(0.0,0.0,4.0);target=vec3(0.0,0.0,-4.0);}\n else if(u_mode<1.5){ro=vec3(0.0,4.4,7.5);target=vec3(0.0,0.45,-2.0);}\n else if(u_mode<2.5){ro=vec3(0.0,1.5,6.2);target=vec3(0.0,0.0,0.0);}\n else{ro=vec3(0.0,4.2,8.0);target=vec3(0.0,1.0,-3.0);}\n vec3 forward=normalize(target-ro);\n vec3 right=normalize(cross(forward,vec3(0.0,1.0,0.0)));\n vec3 up=cross(right,forward);\n vec3 rd=normalize(forward*1.8+right*uv.x+up*uv.y);\n if(u_mode<0.5)rd.xy=rot(sin(u_time*0.13)*0.1)*rd.xy;\n vec3 color=background(rd,uv);\n float distanceTravelled=0.0,glow=0.0,hit=0.0;\n float limit=u_mode<0.5?28.0:24.0;\n vec3 p=ro;\n for(int i=0;i<58;i++){\n   p=ro+rd*distanceTravelled;\n   float d=scene(p);\n   glow+=0.004/(0.08+abs(d))*exp(-0.045*distanceTravelled);\n   if(d<0.018){hit=1.0;break;}\n   distanceTravelled+=max(0.025,d*0.70);\n   if(distanceTravelled>limit)break;\n }\n if(hit>0.5){\n   vec3 n=normalAt(p);\n   float diffuse=max(0.1,dot(n,normalize(vec3(-0.35,0.8,0.55))));\n   float edge=pow(1.0-max(0.0,dot(n,-rd)),2.5);\n   float signal=fft(fract(p.x*0.08+p.z*0.04));\n   vec3 tint=vec3(0.29,0.06,0.71);\n   if(u_mode>0.5&&u_mode<1.5)tint=vec3(0.15,0.28,0.95);\n   if(u_mode>1.5&&u_mode<2.5)tint=vec3(0.52,0.09,0.92);\n   if(u_mode>2.5)tint=vec3(0.77,0.06,0.26);\n   tint=mix(tint,u_theme,0.72);\n   vec3 lit=tint*(0.28+0.9*diffuse+0.55*edge+signal*1.2+u_bass*0.4);\n   if(u_mode>2.5 && p.y>0.08){\n     float windowPattern=step(0.77,fract(p.y*3.3))*step(0.65,fract(p.x*4.5));\n     lit+=vec3(0.95,0.24,0.08)*windowPattern*(0.3+u_high);\n   }\n   float fog=exp(-distanceTravelled*0.067);\n   color=mix(color,lit,fog);\n }\n vec3 emissive=u_mode>2.5?vec3(0.8,0.03,0.15):vec3(0.36,0.06,0.95);\n emissive=mix(emissive,u_theme,0.65);\n color+=emissive*min(glow,1.6)*(0.13+u_mid*0.25);\n color=pow(max(vec3(0.0),vec3(1.0)-exp(-color*1.35)),vec3(0.87));\n gl_FragColor=vec4(color,1.0);\n}"});
